    steps: [
      'Wash the carrots, green bell pepper, baby corn and spring onions. Peel and dice the carrots into small 1 cm pieces, chop the pepper and baby corn into similar bite-sized pieces and slice the spring onions. Crush the garlic and finely chop the red chilli, removing seeds for a gentler heat.',
      'Using a separate board, dice the raw chicken breasts into even 2 cm cubes. Separate the egg, keeping only the white. Toss the chicken pieces with the egg white, cornflour and half the soy sauce, then cover and refrigerate for 10 minutes while you prepare the stir-fry sauce. Wash your hands after handling raw chicken.',
      'Mix the remaining soy sauce with the rice vinegar, sugar, ginger puree and measured black pepper in a cup. Add 3 tablespoons of cold water and stir to dissolve the sugar. Have the roasted peanuts ready beside the hob.',
      'Heat a little of the vegetable oil in a large frying pan over a medium-high heat. Stir-fry the diced carrots for 4 to 5 minutes, add the baby corn and bell pepper and cook for another 3 minutes, then add the peas and stir for 2 minutes until just tender. Transfer the vegetables to a clean plate.',
      'Add the remaining oil to the hot frying pan. Fry the crushed garlic and finely chopped red chilli for 30 seconds, taking care not to burn them. Add the marinated raw chicken in a single layer and stir-fry for around 6 to 8 minutes, turning frequently until the cubes are evenly browned and fully cooked inside.',
      'Check a thicker piece of chicken with a clean food thermometer. It must reach 75°C for 30 seconds. Continue cooking if needed. Return the warm vegetables to the pan and pour in the prepared vinegar and soy sauce, bringing it to a brief simmer for 2 minutes until the sauce coats the chicken and vegetables.',
      'Turn off the heat and fold in the roasted peanuts and sliced spring onions. Spoon onto two plates immediately, showing the glossy diced chicken, carrots, peas, pale baby corn and green pepper as in the real restaurant photo. Use clean serving utensils.',
    ],
