    steps: [
      'Wash your hands and prepare a separate chopping board for the raw chicken. Finely chop the onions and chilli, crush the garlic, and chop the fresh coriander, basil and parsley. Measure the dried herbs and spices.',
      'Heat a heavy, lidded saucepan over a medium heat. Add the chicken thighs and brown for about 4 minutes on each side, turning with utensils used only for raw chicken. Transfer the browned chicken to a clean plate; it is not yet fully cooked.',
      'Melt the butter in the same pan and soften the onions for 7 to 8 minutes. Stir in the garlic, chilli, ground coriander, cumin and mixed herbs for 1 minute until fragrant.',
      'Add the chopped tomatoes and bring to a gentle simmer. Return the chicken and any resting juices to the sauce, then cover and simmer gently for about 25 to 30 minutes, turning once. Add a small splash of water if the sauce starts to catch.',
      'Use a clean food thermometer to check the thickest piece of chicken reaches 75°C for 30 seconds. If not, cover and continue cooking, checking again. Season the sauce with the measured salt and black pepper.',
      'Stir in the chopped coriander, basil and parsley, and simmer uncovered for another 2 minutes. Divide the piping hot chicken and tomato herb stew between two bowls with clean serving utensils.',
    ],
