    steps: [
      'Heat the oven to 200°C (180°C fan). Peel and finely chop the onion, rinse and drain the sweetcorn, and chop the fresh basil. On a separate chopping board for raw meat, dice the chicken thighs into small 2 cm pieces and keep them chilled.',
      'Put the egg in a small saucepan of cold water, bring to the boil and simmer for 9 to 10 minutes until hard-boiled. Cool under running water, peel the shell and cut the egg into two halves. Drain the black olives and measure the raisins ready for layering.',
      'Melt half the butter in a large frying pan over a medium heat. Soften the onion for 6 minutes, then add the raw beef mince and diced raw chicken and cook for about 10 to 12 minutes, breaking up the beef and turning the chicken pieces until browned and cooked through.',
      'Add the ground cumin, measured salt and black pepper and stir for another minute. Use a clean food thermometer to check the thickest chicken piece reaches 75°C for 30 seconds; the beef mince must be completely cooked too. Continue heating if necessary, then take the cooked savoury pino filling off the heat to cool slightly.',
      'Finely chop or crush the sweetcorn kernels with a sturdy fork or potato masher, adding the milk a little at a time and most of the basil. Work until the corn forms a thick, coarse yellow mash, with no large whole kernels. Do not thin it excessively; this needs to form a sweetcorn crust rather than a pourable soup.',
      'Melt the remaining butter in a saucepan over a medium heat, add the corn puree and cook for about 12 to 15 minutes, stirring constantly, until thick enough to hold a spoon mark. Take off the heat and fold in the remaining basil.',
      'Spread the cooked beef and chicken pino into an ovenproof dish. Place the two boiled egg halves, black olives and raisins evenly over the meat so each final portion contains some. Spoon the thick sweetcorn mixture over the top to form an even layer around 2 cm deep, smoothing the surface with a spoon.',
      'Sprinkle the measured sugar thinly over the corn topping and bake for 30 to 35 minutes until the sweetcorn surface is deeply golden and caramelised, as in the authentic source photograph. Check the casserole is piping hot right through; rest for 5 minutes before splitting into two portions and serving.',
    ],
