    steps: [
      'Heat the oven to 180°C (160°C fan). Peel and finely chop the onion. Dice the dried apricots and put them beside the raisins. Wash and cut the carrot, courgette and broccoli into small pieces for the vegetable side. Keep all fresh food away from the raw mince preparation.',
      'Tear the bread into small pieces and soak in around half of the milk for 10 minutes, then mash to a smooth paste. Keep the other half of the milk separate for the egg custard; do not pour it over the raw meat.',
      'Heat the vegetable oil in a large frying pan over a medium heat and soften the onion for 6 minutes. Stir in the curry powder and turmeric for 1 minute until fragrant, then add the beef mince and break it up with a spatula, cooking for about 8 to 10 minutes until browned.',
      'Check that the minced beef is fully cooked and piping hot, reaching 75°C for 30 seconds in the thickest portion using a clean food thermometer. Add the softened bread, diced apricots, raisins, apricot jam, cider vinegar, measured salt and black pepper and stir for another 2 minutes until evenly combined.',
      'Divide the fragrant cooked beef mixture between two small ovenproof dishes. Press gently level, mix through most of the flaked almonds and bake for 18 to 20 minutes until the filling is hot. Handle the little hot dishes with oven gloves.',
      'Beat the two eggs with the reserved milk. Carefully pour this custard over the hot meat in both dishes and place a bay leaf in each. Return to the oven for about 18 to 22 minutes until the custard tops are golden and set right through, not liquid in the centre. Remove and discard the bay leaves before eating.',
      'Meanwhile rinse the basmati rice and cook according to the packet, usually simmering for 10 to 12 minutes then resting covered for 5 minutes. Steam the cut carrot, courgette and broccoli for about 5 to 7 minutes until tender but brightly coloured, then drain.',
      'Place one small golden bobotie casserole on each plate with a compact scoop of rice and the hot steamed vegetables alongside. Add mango chutney in a separate small bowl and garnish the casserole with a little fresh coriander as in the source photograph. Serve immediately.',
    ],
