    steps: [
      'Peel and finely slice the onion, crush the garlic and grate the ginger. Roughly chop the fresh mint and coriander. Use a separate clean board for the raw bone-in chicken thighs, and keep the chicken chilled until the marinade is ready.',
      'Melt the butter in a heavy saucepan over a medium heat and fry the sliced onion for about 15 minutes, stirring, until deep golden. Transfer half of the golden onions to a clean bowl for the final garnish. Let the remaining onions cool briefly.',
      'Mix 100 g of the yoghurt with the garlic, ginger, garam masala, chilli flakes, half the ground turmeric, cinnamon, half the fresh herbs, half the fried onion and the measured salt. Coat the bone-in chicken thighs in this mixture, cover and refrigerate for 30 minutes. Keep the remaining 50 g yoghurt sealed and cold for serving.',
      'While the chicken marinates, wash the basmati rice well and soak it for around 20 minutes, then drain. Bring a separate pan of water to a boil, add the rice and bay leaf, and simmer for 5 to 6 minutes until grains are partly cooked but still firm in the centre. Drain immediately; the rice will finish cooking on top of the chicken.',
      'Spread the marinated chicken and all its yoghurt sauce over the base of the heavy saucepan. Arrange the partly cooked rice over it in an even layer. Mix the remaining ground turmeric with the measured milk and drizzle it across the rice, then scatter the reserved onions and remaining chopped mint and coriander over the top.',
      'Cover the pan with a tight-fitting lid and bring to a gentle simmer for 5 minutes. Reduce the heat to the lowest setting and cook covered for a further 40 to 45 minutes, without stirring. Check occasionally that the base is not burning by listening for steady gentle bubbling and reducing the heat if necessary; add a spoonful of water down the edge if the pan begins to dry.',
      'Before serving, insert a clean food thermometer into the thickest chicken thigh without touching the bone. It must reach 75°C for 30 seconds. If not, cover and continue cooking until the temperature is reached. The rice must be tender and thoroughly hot; if not, add a little hot water and cook a few more minutes.',
      'Leave the covered biryani to rest off the heat for 10 minutes. Gently lift the chicken from the bottom and fluff the golden rice so it is not mashed. Divide between two plates and serve the reserved 50 g cold yoghurt alongside, as shown in the original real food photo.',
    ],
