    steps: [
      'Peel and finely slice the onion, crush the garlic and chop the fresh coriander and parsley. Wash the lemon, finely peel off long strips of yellow zest without the bitter white pith, then cut and juice the lemon. Keep the raw chicken on a separate board from the herbs and vegetables.',
      'In a mixing bowl stir together the ginger puree, garlic, turmeric, cinnamon, two-thirds of the olive oil, lemon juice, half the herbs, salt and black pepper. Coat the bone-in chicken thighs with this fragrant mixture, cover and refrigerate for 20 minutes. Wash your hands and the chopping area after handling the raw chicken.',
      'Warm the remaining olive oil in a heavy, deep lidded pan over a medium heat. Add the sliced onion and soften for 6 to 8 minutes until translucent, stirring so the onions do not brown or catch.',
      'Spread the onions evenly over the bottom of the pan, then nestle the marinated chicken thighs on top skin-side up with all their marinade. Pour in the 100 ml water along the side of the pan rather than washing the spices off the chicken. Bring to a gentle simmer and cover.',
      'Cook on a low to medium heat for 40 minutes, checking occasionally that there is some liquid and adding a splash of water only if it threatens to dry out. The slow-cooked onion and juices make the savoury sauce without needing flour.',
      'Add the green olives and thin lemon zest strips around the chicken. Cover again and simmer for a further 15 to 20 minutes until the chicken is very tender. Insert a clean food thermometer into the thickest flesh without touching bone: it must reach 75°C for 30 seconds; cook longer if necessary.',
      'Remove the lid and let the sauce reduce for about 5 minutes until glossy and slightly thickened. Taste before adding any more salt because the olives are already salty. Scatter the remaining coriander and parsley over the chicken, then serve piping hot with the yellow lemon strips and olives visible in the pan.',
    ],
