    steps: [
      'Using separate clean boards for poultry and vegetables, cut the chicken thigh fillets into evenly sized 2 cm pieces. Finely chop the shallots, garlic and red chilli. Slice the half red onion into thin rings and cut the lime into wedges.',
      'Mix about half the measured ketjap manis with one crushed garlic clove, half the ground coriander, the turmeric and the measured salt. Coat the raw chicken evenly, cover and marinate in the fridge for 25 minutes. Do not leave raw chicken at room temperature and wash all utensils that touched it.',
      'Meanwhile, finely chop most of the roasted peanuts with a sharp knife until they form a coarse crumb; a mortar and pestle also works. Save a teaspoon of chopped nuts for garnish. Make the peanut sauce in a clean pan, separate from the raw chicken marinade.',
      'Heat about a third of the vegetable oil in a saucepan over a medium heat. Soften the sliced shallots, remaining garlic and red chilli for 3 to 4 minutes. Add the peanut crumb, tamarind paste, brown sugar and remaining ketjap manis, then stir in about 160 ml water. Simmer gently for 8 to 10 minutes until a thick spoonable brown peanut sauce forms.',
      'While the sauce cooks, rinse the jasmine rice, place it in a lidded pan with water according to its packet instructions and simmer for around 10 to 12 minutes. Rest off the heat under its lid for a further 5 minutes, then fluff with a clean fork.',
      'Thread the marinated chicken loosely onto clean metal skewers, or pre-soaked wooden skewers, leaving small gaps between pieces. Warm a griddle pan or grill, brush with the remaining vegetable oil and cook the skewers for around 10 to 14 minutes, turning frequently so all sides colour and the meat cooks fully.',
      'Probe the thickest chicken piece with a clean food thermometer to confirm 75°C for 30 seconds. Continue grilling if the temperature is lower. Do not baste with uncooked chicken marinade unless it has first been boiled thoroughly.',
      'Arrange the brown grilled chicken skewers on the sliced red onion, with a generous pool of warm peanut sauce and a lime wedge, as in the original true Commons Sate Ponorogo photograph. Serve the rice separately while everything is piping hot.',
    ],
