    steps: [
      'Wash and dry the bell pepper, then dice it and the onion. Crush the garlic and cut the lime in half. Clean a separate chopping board for handling raw chicken; keep the bone-in chicken thighs chilled until needed.',
      'In a bowl, combine the lime juice, ground cumin, dried oregano, half the crushed garlic, salt and black pepper. Rub over the bone-in chicken thighs, cover and refrigerate for about 15 minutes. Wash your hands and all surfaces touched by raw chicken.',
      'Meanwhile, make around 400 ml of lightly seasoned chicken stock by dissolving half a chicken stock cube and 5 g of chicken stock paste in freshly boiled water. This replaces the original beer and concentrated stock without using too much salt. Rinse the basmati rice and leave it to drain.',
      'Heat the olive oil in a large lidded saucepan over a medium-high heat. Add the marinated chicken thighs skin-side down and brown for 4 to 5 minutes on each side; transfer to a clean plate. The chicken is not yet cooked inside.',
      'Reduce the heat and add the onion and diced pepper to the pan. Stir for about 7 to 8 minutes until softened, then add the remaining garlic, turmeric and passata and cook for another 2 minutes until fragrant.',
      'Return the browned chicken and any plate juices, pour in the warm stock, bring to a gentle boil and simmer for 5 minutes. Sprinkle the rinsed rice evenly around the chicken, cover tightly and cook on low heat for about 20 minutes without stirring, adding a small splash of hot water only if the pan starts to dry out.',
      'Add the peas and sliced green olives and cover for another 5 minutes, until the rice is tender. Use a clean food thermometer to ensure the thickest section of chicken reaches 75°C for 30 seconds, avoiding the bone. If the chicken is not cooked yet, keep simmering, rechecking and adding a little hot water as needed.',
      'Turn off the heat and let the covered dish rest for 5 minutes. Check the rice is fully cooked and the stock absorbed, then fluff gently and divide between two plates. Serve each portion with a hot chicken thigh, golden rice, pepper pieces, olives and peas.',
    ],
