    steps: [
      'Prepare the chicken separately from the other ingredients, washing your hands and equipment after touching raw poultry. Slice the onion and crush the garlic. Tear about two slices (70 g) of bread into a bowl, pour over the milk and leave to soften for 10 minutes.',
      'Put the chicken breasts in a saucepan, cover with water, bring to a gentle simmer and poach for about 15 to 20 minutes, depending on thickness. Use a clean food thermometer to check the thickest part reaches 75°C for 30 seconds. Transfer to a clean plate, then shred the cooked chicken with clean forks.',
      'Meanwhile, peel and cut the potatoes into 2 cm pieces and boil for 15 to 20 minutes until tender. In a second saucepan, simmer the basmati rice with water according to its packet instructions. Hard-boil the eggs for 9 to 10 minutes, then cool and peel them.',
      'Warm the vegetable oil in a large frying pan. Cook the onion for 6 minutes until soft, add the garlic, amarillo chilli paste and turmeric and stir over a moderate heat for another 2 minutes. Avoid burning the chilli paste.',
      'Finely chop the walnuts until crumbly. Mash the soaked bread and milk thoroughly with a potato masher or sturdy fork, then stir in the finely chopped walnuts and add everything to the onion mixture. Cook gently for 8 to 10 minutes, stirring so the creamy sauce thickens but does not catch. Add a little of the chicken poaching water if it becomes too thick.',
      'Stir the shredded chicken and grated Parmesan into the sauce. Heat for 3 to 5 minutes until the chicken and sauce are piping hot throughout; season with the salt and black pepper.',
      'Drain the potatoes and rice. Divide them between two plates, spoon over the creamy chilli chicken and finish with halved boiled eggs and black olives. Serve immediately.',
    ],
