    steps: [
      'Start the rice first: rinse the jasmine rice in a sieve until the water runs mostly clear. Put it in a saucepan with the water required by the packet, bring to a boil, cover and simmer gently for the stated time, usually 10 to 12 minutes. Turn off the heat and leave covered for another 5 minutes.',
      'Finely slice the onion. For the beef, use a clean board and knife and cut the rump steaks across the grain into very thin strips. Chill the meat until needed and wash the knife and board before other preparation.',
      'Peel and grate 10 g of the ginger for the sauce. Cut the remaining 5 g into thin matchsticks and mix with the rice vinegar in a small bowl; leave the garnish to quickly pickle while the onions cook.',
      'Make up around 200 ml of beef stock using the 15 g of beef stock paste and hot water, checking the packet concentration. Add the stock to a wide saucepan with the soy sauce, mirin, Chinese rice wine, sugar and grated ginger. Bring to a gentle simmer.',
      'Add the sliced onion and cook in the bubbling stock for 5 to 6 minutes until soft and translucent. Spread the thin beef strips out across the broth, separating the pieces with a clean spoon rather than adding them in a large clump.',
      'Simmer the beef for 3 to 5 minutes until every slice has changed colour, is cooked all the way through and is piping hot. If any piece is still raw inside, cook further before serving. Stir gently to keep the thin pieces tender.',
      'Divide the hot rice between two bowls, spoon the beef and onions over it and add some of the broth. Finish with a little of the quick-pickled ginger, if liked. Serve immediately.',
    ],
