    steps: [
      'Heat the oven to 220°C (200°C fan). Wash and cut the potatoes into thin chips, keeping the skins on if liked. Dry thoroughly, toss with about half the measured vegetable oil and spread across a baking tray. Bake for 25 to 30 minutes, turning halfway, until crisp on the outside and soft within.',
      'Meanwhile rinse the basmati rice, add to a saucepan with the packet quantity of fresh water, and simmer covered for around 10 to 12 minutes. Turn off the heat and let it stand, still covered, for 5 minutes before fluffing with a fork.',
      'Using a clean board, cut the rump steak across the grain into thin strips. Toss the beef with the soy sauce, red wine vinegar and crushed garlic, cover and refrigerate for 15 minutes while the chips and rice cook.',
      'Slice the red onion into thick wedges, halve the baby plum tomatoes, and roughly chop the coriander. Mix the amarillo chilli paste with a tablespoon of water ready for the hot pan.',
      'Heat half the remaining vegetable oil in a large frying pan until very hot. Lift the beef strips from the marinade and sear in two batches, about 90 seconds on each side, so they brown rather than steam. Set aside on a clean plate. Do not reuse uncooked marinade without boiling it.',
      'Add the remaining oil to the frying pan, fry the onion for 2 minutes until still slightly crisp, then stir in the amarillo chilli paste and halved tomatoes. Return the cooked beef and any juices and simmer for another 2 to 3 minutes, ensuring everything is piping hot. Pour in the reserved marinade only if you boil it thoroughly.',
      'Toss some of the crisp chips through the pan sauce, leaving the rest beside the beef. Divide the rice between two plates, spoon over the beef, tomatoes and onion, add the chips and scatter with fresh coriander. Serve immediately.',
    ],
