    steps: [
      'Heat the oven to 220°C (200°C fan). Wash and dice the potatoes into even 2 cm cubes. Toss with about half the vegetable oil and spread onto a baking tray. Roast for 25 to 30 minutes, turning halfway, until golden and soft all the way through.',
      'Using a clean board, finely slice the onion and mushrooms, chop the fresh parsley and dice the pickled cucumber. Cut the tomato into wedges for serving, keeping these ready-to-eat ingredients away from raw beef preparation.',
      'Cut the raw rump steak across the grain into thin 1 cm strips on a separate chopping board, pat dry with paper and season with the measured salt and black pepper. Keep the meat chilled until the frying pan is hot, then discard the meat papers.',
      'Heat the remaining vegetable oil in a large frying pan until shimmering. Sear the beef strips in two batches for 2 minutes per side so they brown rather than release water. Transfer to a clean plate; they will finish cooking in the creamy sauce.',
      'Turn the heat down to medium-high and cook the sliced mushrooms in the same frying pan for about 5 minutes until their water evaporates. Add the butter and onion and fry for another 6 minutes until softened and lightly golden.',
      'Stir the plain flour and smoked paprika into the onion and mushroom mixture for 1 minute. Dissolve the stock paste in around 220 ml freshly boiled water and add it gradually, stirring constantly until the sauce is smooth, thickened and bubbling.',
      'Lower the heat and stir in the soured cream and mustard. Return the browned beef and any clean resting juices, then simmer gently for around 4 to 5 minutes until the meat is cooked to preference and piping hot and the sauce coats the strips, avoiding a rapid boil that could split the cream.',
      'Scatter the chopped parsley over the stroganoff. Divide the creamy beef and mushrooms between two warm plates, arranging the golden roast potato cubes, diced pickled cucumber and fresh tomato wedges alongside in distinct portions, matching the authentic original Commons photograph.',
    ],
