    steps: [
      'Finely dice the tomato, half an onion and green chilli, removing the chilli seeds if you prefer less heat. Crush the coriander seeds roughly using the back of a spoon, then chop the fresh coriander leaves and stems.',
      'Wash your hands before handling the raw beef. In a large bowl, combine the beef mince with breadcrumbs, the beaten egg, onion, chilli, crushed coriander seeds, pomegranate molasses, fresh coriander and the measured salt. Mix gently until evenly distributed, avoiding overworking it into a dense paste.',
      'Fold in the diced tomato last so the patties stay firm. Cover the bowl and refrigerate for around 20 minutes, keeping the raw mince away from other food. Wash the bowl-side equipment and hands before preparing the rest of the meal.',
      'Divide the chilled mixture into four and shape each into a wide, flat patty around 1 cm thick with damp hands. Press the edges together to avoid cracks. If the mixture is too wet, let it rest for a further few minutes before frying.',
      'Heat the vegetable oil in a large frying pan over a medium heat. Add the patties without overcrowding and cook for around 5 to 6 minutes per side, turning carefully, until well browned, crisp at the edges and cooked right through. Check the centre of the thickest patty with a clean food thermometer; minced beef must reach 75°C for 30 seconds before serving.',
      'While the patties cook, spoon the Greek yoghurt into two small bowls. Cut the lemon into wedges and warm the pitta breads briefly in a dry pan or toaster, using clean equipment.',
      'Divide the golden beef chapli patties between two plates. Serve with the warm pitta, cooling yoghurt and lemon wedges, squeezing lemon over the patties just before eating. Do not place cooked patties back onto a plate used for raw meat.',
    ],
