    steps: [
      'Preheat the oven to 220°C (200°C fan). Wash and cut the potatoes into thin chips. Pat dry, toss with around 15 ml of the measured vegetable oil and spread across a baking tray. Bake for 25 to 30 minutes, turning halfway, until crisp and cooked through.',
      'Wash and dry the lettuce, slice the tomato and halve the green olives. Slice the burger buns horizontally. Keep the salad vegetables away from any raw meat board or utensils.',
      'Cut the beef rump steaks in half to make two thin portions and place each piece between two sheets of cling film. Gently flatten to about 5 mm thick, season both sides with the measured salt and black pepper and keep chilled until ready to fry.',
      'In a large frying pan over a medium heat, cook the streaky bacon for about 5 to 8 minutes, turning until crisp and thoroughly cooked. Transfer to kitchen paper. Warm the sliced ham in the pan for 1 minute if preferred, then move to a clean plate.',
      'Turn the frying pan to medium-high heat and add a little of the remaining oil. Sear the thin steak portions for about 2 minutes per side, adjusting to thickness and preference; check the beef is cooked to the eater’s preferred doneness, and is piping hot for those who need it thoroughly cooked.',
      'Put half the mozzarella over each steak and cover the pan briefly for around 1 minute to melt the cheese. Transfer to a clean plate. Add the remaining oil to a clean area of the pan and fry two eggs until their whites are completely set, turning if fully firm yolks are wanted.',
      'Lightly toast the split buns in the dry pan. Spread mayonnaise over both halves of each bun, then stack lettuce, tomato, the warm cheesy steak, ham, crispy bacon and a cooked egg. Close each sandwich with the top bun and secure with a short skewer if needed, adding a green olive to the top.',
      'Serve the chivito sandwiches immediately with the oven chips alongside, as pictured in the original source photograph. Remove any toothpicks or skewers before eating.',
    ],
