    steps: [
      'Rinse the jasmine rice and cook it in fresh water according to the packet, covered for around 10 to 12 minutes, then rest covered off the heat for another 5 minutes. Keep it hot until serving.',
      'Cut the rump steak across the grain into 2 cm strips on a separate clean meat chopping board. Mix with the oyster sauce, soy sauce, two crushed garlic cloves, sugar and half the measured black pepper. Cover and refrigerate to marinate for 20 minutes.',
      'Meanwhile wash and dry the lettuce, slice the tomatoes, half cucumber and half red onion, and arrange the salad on two plates. Reserve the remaining crushed garlic and keep uncooked beef utensils away from the vegetables.',
      'Squeeze the limes into a small bowl, add the remaining black pepper and a pinch of the salt. Mix to make a sharp dipping sauce, adjusting with a tablespoon of water if it is too strong.',
      'Heat half the vegetable oil in a large frying pan over a high heat. Fry the marinated beef strips in small batches, allowing around 2 minutes per side until properly browned and piping hot, then set on a clean plate. Boil any remaining marinade thoroughly before using it as sauce.',
      'Add the remaining oil to the same hot pan and fry the eggs until the whites are completely set; turn briefly if preferred, leaving the yolks soft only if suitable for those eating them. Pack the cooked rice into a small bowl and turn one mound out onto each plate, placing a fried egg on top.',
      'Pile the sizzling beef beside the rice and salad. Drizzle a little of the hot pan juices over the meat and serve the pepper-lime sauce in a separate bowl for dipping. Serve straight away.',
    ],
