    steps: [
      'Finely grate the half onion. Mix the raw beef mince with the cornflour, ginger puree, ground allspice, the measured salt and black pepper. Add the 80 ml cold water slowly, stirring until the mixture is smooth and slightly sticky; fold in the grated onion at the end.',
      'Cover the bowl and refrigerate the seasoned mince for 20 minutes so the mixture becomes easier to shape. Keep raw meat separate from everything cooked, and wash your hands and preparation surfaces thoroughly.',
      'Peel the potatoes and cut into evenly sized pieces. Put in fresh water, bring to a boil and simmer for 15 to 20 minutes until soft. Drain well and mash with about a third of the measured butter and a spoonful of hot cooking water. Keep warm covered.',
      'With clean wet hands, shape the chilled mince into four thick oval patties. Heat another third of the butter in a frying pan over medium heat and brown the patties for about 4 minutes on each side. Move them to a clean plate; they will finish cooking in gravy.',
      'Add the plain flour to the remaining pan fat and cook for 1 minute, stirring. Dissolve the beef stock paste in about 250 ml of freshly boiled water and gradually add it to the flour, whisking to make a thick brown gravy without lumps.',
      'Put the browned patties back into the gravy and simmer gently, covered, for about 18 to 20 minutes. Check the centre of the thickest beef-mince patty reaches 75°C for 30 seconds on a clean food thermometer. Do not serve until it does; simmer longer if needed.',
      'While the beef simmers, cook the peas in a small saucepan of boiling water for about 3 to 4 minutes, or according to their packet, and drain thoroughly. Warm the potato mash if needed, without leaving it at room temperature.',
      'Divide the mashed potatoes and peas between two plates, add the cooked oval beef patties and spoon over the rich brown gravy. Serve a small dollop of redcurrant jelly alongside for the sharp-sweet note that lingonberries give to the traditional Norwegian dish.',
    ],
