    steps: [
      'Finely chop half an onion. Tear the bread into small pieces and soak in about 60 g of the crème fraîche for 10 minutes, then mash with a fork to a soft paste. Keep the remaining crème fraîche sealed in the fridge for the gravy.',
      'Melt a small knob of the butter in a frying pan over medium heat. Gently soften the onion for around 6 minutes without browning, then leave it to cool so it will not partly cook the raw mince while mixing.',
      'Wash your hands and combine the beef mince, pork mince, softened bread, cool onion, egg, ground allspice, measured salt and black pepper in a large bowl. Mix until evenly combined, then form walnut-sized meatballs with wet hands. Keep the meatballs chilled until ready to fry.',
      'Peel the potatoes, cut into even 3 cm chunks and simmer in salted water for around 15 to 20 minutes until tender. Drain thoroughly and mash with a little of the remaining butter and a spoonful of the potato cooking water, keeping them hot for serving.',
      'Melt most of the remaining butter in the frying pan and brown the meatballs in batches for about 8 to 10 minutes, rolling them so all sides colour evenly. Keep the browned meatballs on a clean plate; they are not necessarily fully cooked yet.',
      'Add the plain flour to the butter left in the pan, stir for 1 minute and gradually pour in around 250 ml hot water mixed with the beef stock paste. Stir to a smooth gravy and simmer for 3 to 4 minutes. Reduce the heat and stir in the remaining crème fraîche and soy sauce gently, without boiling hard.',
      'Return the meatballs and any juices to the simmering gravy, cover and cook gently for about 7 to 10 minutes, checking the centre of the thickest meatball reaches 75°C for 30 seconds on a clean food thermometer. If not, cook further and check again before serving.',
      'Arrange the browned meatballs next to the hot mashed potatoes, spoon the creamy gravy separately over or alongside, and add a little redcurrant jelly on the side. The original Commons photograph shows the plainly browned cooked meatballs before the optional accompaniments are added.',
    ],
