    steps: [
      'Rinse the jasmine rice thoroughly and put it in a saucepan with the water directed on the packet. Cover and simmer for about 10 to 12 minutes until tender, then leave off the heat, still covered, for another 5 minutes.',
      'Peel and crush the garlic cloves and finely chop two red chillies, removing their seeds if you prefer milder heat. Strip the Thai basil leaves and set them aside. Keep the raw pork mince refrigerated until the pan is hot.',
      'In a small bowl combine the oyster sauce, fish sauce, dark soy sauce and sugar with 2 tablespoons of water. Stir thoroughly now so all the seasoning is ready before the stir fry starts.',
      'Heat about half the vegetable oil in a large frying pan over a medium-high heat. Fry the garlic and chilli for around 30 seconds until fragrant, watching carefully so the garlic does not burn.',
      'Add the raw pork mince and stir fry, breaking it into small pieces with a wooden spatula, for around 6 to 8 minutes until evenly browned and cooked throughout. Use a clean food thermometer to check a portion reaches 75°C for 30 seconds; cook longer if necessary.',
      'Pour in the prepared savoury sauce and simmer for 2 minutes until it coats the hot pork evenly. Turn off the heat, add most of the Thai basil and stir until it wilts. Keep the pork stir fry hot while you finish the eggs.',
      'In a second hot pan or a clean area of the frying pan, add the remaining vegetable oil and fry both eggs for around 3 minutes until the whites are completely set and the edges crisp. Turn briefly if fully cooked yolks are preferred.',
      'Divide the freshly cooked rice into two mounds on warm plates. Spoon the fragrant pork and Thai basil stir fry alongside and top each serving with a fried egg and a few reserved basil leaves, matching the exact original Commons photograph.',
    ],
