    steps: [
      'Cut the pork loin steaks into even 2 to 3 cm cubes using a dedicated raw-meat board and knife. Keep the pork chilled while preparing the marinade and wash the equipment and your hands afterwards.',
      'Zest and juice half the lemon into a bowl and stir in most of the olive oil, dried oregano, one crushed garlic clove, half the measured salt and black pepper. Coat the pork pieces, cover and refrigerate for around 20 minutes to pick up the lemon and herb flavour.',
      'While the pork marinates, grate the cucumber and gently squeeze out its excess water. Mix it into the Greek yoghurt with the second crushed garlic clove, a teaspoon of the remaining olive oil, the other half of the salt and a little more lemon juice. Chill the tzatziki until serving.',
      'Heat a grill or griddle pan to medium-high. Thread the meat onto the skewers with a little space between pieces so the heat reaches every surface. If using wooden skewers, soak them in water first and keep them away from any direct flame.',
      'Grill the pork skewers, turning regularly, for about 12 to 16 minutes depending on their thickness, until deeply browned and completely cooked through. Use a clean food thermometer to check the thickest piece is at least 75°C for 30 seconds; cook further if necessary.',
      'Rest the cooked skewers on a clean plate for 5 minutes. Warm the pitta breads briefly in the griddle or toaster, then divide between plates with the cooked lemon and oregano pork, lemon wedges and the chilled tzatziki. Never use the raw meat marinade as a dressing.',
    ],
