    steps: [
      'Finely grate the half onion, and shred the green cabbage into thin short strips. Peel the potatoes and halve any large ones so they cook evenly. Keep raw meat separate from the vegetables.',
      'Wash your hands, then mix the pork mince and beef mince with the grated onion, egg, plain flour, 75 ml of the measured milk, allspice, salt and black pepper in a bowl. Stir thoroughly until combined and slightly sticky; cover and refrigerate for 20 minutes so the patties keep their shape.',
      'Bring a saucepan of lightly salted water to a boil. Add the prepared potatoes and simmer for around 15 to 20 minutes until tender throughout, then drain and keep warm with the lid on.',
      'Put the finely shredded cabbage into a second saucepan with about 3 tablespoons of water. Cover and cook over a medium-low heat for 7 to 8 minutes, stirring occasionally, until soft but not mushy. Stir in the extra 100 ml milk and crème fraîche, and simmer gently for another 4 minutes until lightly creamy and piping hot.',
      'Use a wet tablespoon to scoop the chilled mince mixture into six small oval patties about 1 cm thick. Melt about two-thirds of the butter in a wide frying pan over medium heat. Fry the patties in two batches for around 5 to 6 minutes on each side, until deeply browned and cooked fully through. Add a little remaining butter if the pan dries out.',
      'Check the centre of the thickest frikadeller with a clean food thermometer: it must reach 75°C for 30 seconds because the meat is minced. Continue cooking if necessary. Move the cooked patties to a clean warm plate, discarding any utensils used only on raw mince.',
      'Divide the boiled potatoes and creamy shredded cabbage between two plates. Add the hot brown Danish-style frikadeller beside them, spooning over any clean cooking juices. The authentic Commons photograph shows these same browned patties, whole boiled potatoes and creamed pale cabbage, with no red pickles.',
    ],
