    steps: [
      'Rinse the jasmine rice in a sieve until the water runs mostly clear. Put it into a lidded saucepan with the water specified by the packet, bring to a boil and simmer gently for around 10 to 12 minutes. Take off the heat and leave the lid on for another 5 minutes.',
      'While the rice cooks, pat the pork loin steaks dry. Put them on a board used only for raw meat and gently flatten to around 1 cm thick. Trim or nick any thick fat rim so they do not curl, then wash your hands and clean the board and utensils.',
      'Beat one egg in a shallow bowl, place the plain flour in a second dish and the panko breadcrumbs in a third. Lightly dust each pork steak with flour, dip into beaten egg and coat generously with panko without pressing too hard.',
      'Heat around 35 ml of the vegetable oil in a wide frying pan over a medium heat until hot but not smoking. Shallow-fry the coated cutlets for about 4 to 5 minutes per side, adjusting for thickness, until crisp and deeply golden. Check the thickest part reaches 75°C for 30 seconds with a clean food thermometer; continue frying if needed. Transfer to a clean plate to rest.',
      'Meanwhile thinly slice the onion and spring onion. Mix the vegetable stock paste and miso paste with 200 ml hot water, stirring until dissolved. Add the soy sauce, mirin and sugar to this broth and bring to a simmer in a clean, shallow saucepan.',
      'Stir the sliced onion into the broth and simmer for around 5 minutes until soft. Slice the cooked pork cutlets across the grain into strips, keeping them together, then lay the slices gently in the simmering onion broth.',
      'Beat the remaining two eggs in a small clean bowl. Pour slowly around the pork, cover and simmer for 2 to 3 minutes until the egg is completely set and the broth is piping hot. Do not serve raw or unset egg.',
      'Divide the hot rice between two bowls and carefully slide one saucy cutlet and its tender onion and egg onto each mound. Scatter the sliced spring onion over the top and serve the genuine photographed katsudon immediately.',
    ],
