    steps: [
      'Wash the potatoes, peel if preferred and chop into 3 cm pieces. Soak the potato pieces in a bowl of cold water for 10 minutes while preparing everything else, then drain. Peel and cut the carrot into thick half-moons and slice the onion into wedges.',
      'On a separate meat board, cut the pork loin steaks across the grain into very thin bite-sized strips, then refrigerate. Top and tail the green beans and chop into short sections. Keep utensils that touched raw pork apart from the ready-to-eat food.',
      'Dissolve the vegetable stock paste and miso paste in about 300 ml freshly boiled water. Stir the mirin, soy sauce, Chinese rice wine and sugar into the stock so the sauce is ready before cooking.',
      'Warm the vegetable oil in a deep frying pan over medium heat. Soften the onion for about 3 minutes, then add the sliced pork and stir-fry for 4 to 5 minutes until it loses its raw colour and begins to brown lightly. The pork will finish cooking in the liquid.',
      'Add the drained potato pieces and carrot and turn them in the cooking juices for 2 minutes. Pour in the seasoned stock, bring to a boil, then reduce to a gentle simmer.',
      'Cover with a lid or a circle of greaseproof paper with a steam hole and simmer for 20 to 25 minutes until the potatoes and carrots are tender. Check the pork pieces are thoroughly cooked through and piping hot; if any remain pink or undercooked, simmer longer.',
      'Meanwhile, soak or boil the rice noodles according to their packet instructions until softened but still holding their shape, then drain. Add the rice noodles and green beans to the simmering pan for the last 4 to 5 minutes and stir gently so the noodles soak up some glossy broth.',
      'Rest covered for 5 minutes. Divide the pork, carrots, potato chunks and translucent noodles between two bowls, with a little savoury broth. The actual source photograph features pork, not the beef specified in its imported original method; this version corrects the meat and labels the market-supported rice-noodle adaptation.',
    ],
