    steps: [
      'Wash your hands, prepare the fresh shallots and garlic, then clean your chopping board before handling the raw fish. Cut the haddock into generous bite-sized pieces, carefully removing any bones. Keep the fish chilled while preparing the sauce.',
      'Finely chop the shallots and grate the ginger. Crush the dried lime leaves between your fingers. Combine the lemongrass puree, ginger, garlic, shallots, turmeric and half the lime leaves in a small bowl to make a fragrant paste.',
      'Warm half the coconut milk in a saucepan over a medium heat. Stir in the spice paste for about 4 to 5 minutes, until fragrant. Take the pan off the heat and let the mixture cool until just warm, not hot enough to cook an egg on contact.',
      'Beat the egg in a clean bowl with the remaining coconut milk, fish sauce, brown sugar and salt. Whisk this slowly into the warmed spice sauce. Fold through the pieces of raw fish and refrigerate for 10 minutes while you prepare the cooking vessels.',
      'Set a large covered saucepan or steamer with enough water underneath, and bring it to a steady simmer. Line two heatproof ramekins with the baby spinach and spoon the fish and coconut sauce over it, dividing the pieces evenly. Do not overfill the ramekins.',
      'Steam the two filled ramekins, covered, for around 20 to 25 minutes, adjusting to their depth. Check the fish is opaque, flakes easily and is piping hot throughout; the egg mixture must also be fully set. Continue steaming if needed, rather than serving a runny or partly cooked centre.',
      'While the fish steams, rinse the basmati rice and cook it in fresh water according to the packet instructions. Once tender, let it rest covered for 5 minutes. Warm the creamed coconut with a tablespoon of water to make a smooth, spoonable topping.',
      'Spoon the coconut topping over the cooked fish, add the remaining lime leaves and serve immediately with the hot rice. Use clean utensils and discard any raw fish marinade or contaminated leftovers.',
    ],
