    steps: [
      'Wash your hands and prepare two separate chopping areas for the fish and vegetables. Cut the haddock fillets into generous pieces, remove any visible bones and keep the raw fish and prawns chilled. Finely slice the onion, pepper and spring onions, crush the garlic, then chop the fresh coriander.',
      'Gently mix the fish pieces with the juice of half the lime, a pinch of the measured salt and a pinch of black pepper. Keep the fish refrigerated while preparing the vegetable base. Do not leave raw fish at room temperature to marinate.',
      'Rinse the basmati rice in a sieve and cook it in a covered saucepan according to the packet instructions. Allow around 10 to 12 minutes for simmering and a further 5 minutes to rest off the heat. Keep warm with the lid on.',
      'Meanwhile, heat the olive oil over a medium heat in a wide, lidded saucepan. Soften the onion and pepper for around 7 minutes, stirring. Add the garlic and smoked paprika and cook for another minute, without letting the garlic scorch.',
      'Add the chopped tomatoes and remaining salt and black pepper. Simmer uncovered for 6 to 8 minutes until the tomatoes thicken into a sauce. Pour in the coconut milk, stir gently and return to a simmer.',
      'Nestle the raw haddock pieces and raw prawns into the coconut sauce in a single layer. Cover and simmer gently for 8 to 10 minutes depending on thickness, without stirring hard enough to break up the fish. Check that the fish is opaque and flakes easily, the prawns are opaque throughout, and everything is piping hot. If not, continue cooking and recheck before serving.',
      'Scatter the spring onions and chopped coriander over the bubbling stew and allow another minute to warm through. Serve the hot coconut fish and prawn stew with the rice and the remaining lime cut into wedges. Avoid cross-contamination by using clean serving utensils.',
    ],
