    steps: [
      'Rinse the jasmine rice until the water runs mostly clear. Cook in fresh water according to its packet, usually 10 to 12 minutes simmering, then rest covered for 5 minutes. Spread the cooked rice thinly over a clean shallow plate, refrigerating promptly for 15 to 20 minutes until cool and separated. Never leave cooked rice standing at room temperature.',
      'While the rice cools, peel and finely dice the carrot, chop the ham into small cubes, thinly slice both spring onions and measure the peas. Keep the prawns refrigerated until ready to use, following the packet instructions for thawing if frozen.',
      'Break the two eggs into a clean bowl and beat lightly. In another small bowl mix the Chinese rice wine with the soy sauce, measured salt and black pepper so the stir fry sauce is ready in advance.',
      'Heat about one-third of the vegetable oil in a large wok or frying pan over medium-high heat. Add the beaten eggs and let them set, then scramble into small pieces for about 1 to 2 minutes. Remove to a clean plate.',
      'Add a little more oil and the diced carrot, cook for 2 minutes, then add the peas, chopped ham and king prawns. Stir fry for around 4 to 5 minutes until the carrots are tender and the prawns are opaque, thoroughly cooked and piping hot. Return any cooked ingredients only to clean plates.',
      'Increase the heat to medium-high and add the remaining oil. Tip in the cooled rice and stir fry for 3 to 4 minutes, breaking up clumps and turning continuously until every grain is piping hot. Do not serve partially reheated rice.',
      'Return the cooked eggs, prawns, ham and vegetables to the wok. Pour in the prepared soy and wine sauce and stir fry for another minute until the whole dish is hot and glossy. Scatter most of the spring onion through the rice.',
      'Divide into two bowls, finishing with the remaining spring onion. Each portion should show separate rice grains, prawns, egg pieces, ham, peas and carrot, as in the exact Commons photograph from a Hong Kong fried-rice restaurant.',
    ],
