    steps: [
      'Heat the oven to 220°C (200°C fan). Wash the potatoes and cut into even chips. Pat them dry, toss with the olive oil and spread on a baking tray. Bake for about 25 to 30 minutes, turning halfway, until crisp outside and tender throughout.',
      'Keep the fresh mussels refrigerated until the moment you prepare them. Check their use-by date and any retailer instructions. Discard any with cracked or broken shells. Tap any gaping mussels; discard those that do not close. Pull off beards and scrub and rinse the shells briefly in cold running water. Do not leave live mussels soaking in standing water.',
      'Finely chop the shallots and half a leek, crush the garlic, strip the thyme leaves and chop the flat leaf parsley. Set the bay leaf to one side so it can be removed after cooking.',
      'Melt the butter in a very large wide saucepan over a medium heat. Gently soften the shallots and leek for 5 to 6 minutes without browning. Add the garlic and fresh thyme for another minute, stirring so the garlic does not burn.',
      'Mix the vegetable stock paste with 220 ml of freshly boiled water, add to the pan with the bay leaf and bring the liquid to a vigorous boil. Cover for 2 minutes to develop the fragrant broth.',
      'Tip in the cleaned live mussels, cover immediately and boil or steam vigorously for about 5 to 7 minutes, shaking the closed pan once or twice using oven gloves. Cook until the mussels have opened and the flesh is firm and piping hot throughout; if any remain closed, discard them rather than forcing them open. Follow any longer timing specified on the packet.',
      'Carefully lift the lid away from your face, remove the bay leaf and scatter the chopped parsley and measured black pepper over the cooked mussels. Squeeze in the juice of half the lemon and taste the hot broth; adjust with the remaining lemon if desired.',
      'Divide the hot mussels and their herb broth between two deep bowls with clean utensils, discarding any unopened shells. Serve with the crispy oven chips on the side, as shown beside the original photographed mussel pot. Do not save leftover raw mussels at room temperature.',
    ],
    sourceStepIngredientIds: [[], [], [], [], [], [], ['ut-moules-marinieres-ingredient-10'], []],
