    steps: [
      'Rinse the red split lentils well and drain. Put them in a saucepan with 350 ml water and the measured turmeric. Bring to a boil, then simmer gently, partly covered, for 20 to 25 minutes until very soft, stirring occasionally and adding a little more water if it starts to dry out.',
      'Meanwhile rinse the basmati rice. Cook it in a separate lidded saucepan with the water specified on the packet, generally simmering for 10 to 12 minutes. Leave covered off the heat for another 5 minutes. Keep warm for serving.',
      'Finely chop the half onion and crush the garlic. Slice the red chilli into rings. Warm a small knob from the measured butter in a frying pan, soften the onion for 5 minutes, add the chopped tomatoes and simmer for another 5 minutes into a thick aromatic base.',
      'Stir the onion and tomato base into the soft lentils. Mash a few spoonfuls against the side of the saucepan to thicken the dal, adding a splash of hot water if necessary. Season with half the salt and taste; keep the lentils gently simmering.',
      'In a separate small pan, heat the remaining butter over a medium heat until foaming. Add the mustard seeds carefully and allow them to pop, then quickly add the cumin seeds, garlic and red chilli. Stir for 30 to 60 seconds until fragrant but not burned. Add the ground coriander just before taking the pan off the heat.',
      'Carefully pour the hot spiced butter over the cooked dal. It should sizzle on contact; stir gently so the spices distribute through the lentils, then cook for another minute. Taste, add the remaining salt if needed, and check the dal is piping hot.',
      'Divide the rice between two warm bowls. Spoon the thick golden dal beside or over it and scatter any fried chilli and garlic from the pan on top. Serve while hot.',
    ],
