    steps: [
      'Peel the potatoes and half an onion. Grate both finely into the same bowl using a box grater, taking care of your fingertips. Mix immediately so the onion distributes through the potato and slows browning.',
      'Leave the grated potato mixture to stand for 3 minutes, then carefully pour off the excess liquid. Keep the pale potato starch that settles at the bottom of the bowl, and stir it back through the grated potato. The mixture should be damp but not runny.',
      'Season the grated potato and onion with the measured salt and black pepper. Do not add flour or egg: the potato starch is enough to hold these traditional small pancakes together.',
      'Heat a generous layer of the measured vegetable oil in a large frying pan over a medium heat. Spoon in small portions of the mixture and flatten each to around 5 mm thick, leaving space between pancakes. Cook in batches rather than overcrowding the pan.',
      'Fry each pancake for 3 to 4 minutes on the first side until crisp and deep golden, then turn carefully and fry the other side for another 3 to 4 minutes. Check that the inside is tender and no raw potato remains. Adjust the heat if the outside browns before the middle cooks.',
      'Lift the cooked pancakes onto kitchen paper, then keep them warm while the remaining batches fry. Finely chop the fresh dill and stir half into the soured cream, keeping the rest for garnish.',
      'Divide the hot, golden potato pancakes between two plates. Add the dill soured cream on the side, sprinkle with the remaining dill and serve immediately while the edges stay crisp.',
    ],
