    steps: [
      'Heat the grill to medium-high. Wash the bell peppers and green chilli, then place the whole bell peppers on a baking tray. Grill for around 12 to 15 minutes, turning as their skin blackens in patches; keep a close watch so the flesh does not burn.',
      'Transfer the hot peppers to a covered bowl and leave for 8 to 10 minutes so the skins loosen. Once cool enough to handle, peel away most of the blackened skin, discard stems and seeds, then cut the sweet roasted flesh into short strips.',
      'Heat the oven to 200°C (180°C fan). Finely chop the onion, crush the garlic, dice the tomatoes and chop the green chilli, removing the seeds if you prefer less heat.',
      'Melt the butter in a medium frying pan over a moderate heat. Soften the onion for 6 minutes, then stir in the garlic, green chilli and plain flour for another minute until fragrant. The flour helps bind the creamy baked sauce.',
      'Add the chopped tomatoes and simmer for 8 to 10 minutes until much of their liquid has evaporated into a thick bright red-orange sauce. Stir in the peeled pepper strips, measured salt and black pepper and heat for a further 2 minutes.',
      'Break up the feta with a fork and mix with the ricotta cheese in a clean bowl. Fold both cheeses through the warm pepper and tomato mixture, stirring until distributed but still showing some pale cheese pieces. Do not boil hard or the cheese may separate.',
      'Spoon the rich orange pepper and cheese mixture into a shallow ovenproof dish. Bake uncovered for 18 to 20 minutes until bubbling and just golden on top, similar to the real photographed Albanian fërgesë. Check the centre is piping hot.',
      'Warm the two pitta breads according to their packet instructions. Rest the bubbling baked dish for 3 minutes then divide between two plates, with warmed pitta on the side for scooping.',
    ],
