    steps: [
      'Peel and finely slice the onions. Melt the butter in a frying pan over a medium-low heat, add the onions and cook gently for 20 to 25 minutes, stirring regularly, until deep golden and sweet. Do not turn the heat so high that they burn before softening.',
      'While the onions cook, whisk the plain flour, eggs, water, ground allspice and measured salt in a large bowl. Beat the mixture firmly with a wooden spoon for around 5 minutes, until smooth, thick and stretchy. It should drop slowly through the holes of a wide-holed colander rather than pour like pancake batter.',
      'Bring a large saucepan of lightly salted water to a rolling boil. In small batches, hold a sturdy wide-holed colander over the pan and push a portion of the batter gently through its holes with a spatula to form short pieces. Use oven gloves or a heat-resistant tool to avoid steam burns.',
      'The fresh spätzle will float after around 1 to 2 minutes. Give each batch another minute to cook, then lift with a slotted spoon into a warm serving bowl. Repeat with the remaining batter, maintaining a steady boil. Test a piece to ensure it has no raw floury centre.',
      'Grate the mature Cheddar while the noodles cook. Layer the hot drained spätzle with the grated cheese in the warm dish, folding gently until the cheese melts and coats the pieces. If needed, loosen with a spoon of hot cooking water, but do not make it runny.',
      'Finely chop the chives. Spoon the soft golden onions over the cheesy spätzle and sprinkle liberally with the chives. Divide between two warm plates or serve in the warm pan immediately.',
    ],
