    steps: [
      'Prepare the onions by peeling and slicing them as thinly as possible. Crush the garlic. Rinse the brown lentils and risotto rice separately, and drain the chickpeas. Measure out the short pasta, tomatoes, vinegar, cumin and chilli flakes.',
      'Heat about 45 ml of the vegetable oil in a large frying pan over a medium heat. Fry the thin onion slices for around 20 to 25 minutes, stirring often, until a deep golden colour. Remove with a slotted spoon to kitchen paper to crisp up, keeping the flavoured oil for the rice.',
      'While the onions cook, simmer the brown lentils in a separate pan of fresh water for around 20 to 25 minutes or until tender but not falling apart, then drain. In another pan, cook the short pasta in boiling water for the packet time, usually 9 to 12 minutes, then drain.',
      'Heat around 10 ml of the onion oil in a lidded saucepan, add the rinsed rice and toast for 2 minutes. Add water according to the packet, cover and simmer gently until the rice is cooked, usually around 15 to 18 minutes, then leave covered off the heat for 5 minutes.',
      'In the emptied frying pan, warm the remaining 10 ml of vegetable oil. Add the crushed garlic and cook for 30 seconds, then carefully add the white wine vinegar. Allow it to bubble for a minute before adding the chopped tomatoes, ground cumin, chilli flakes and salt.',
      'Simmer the tomato sauce for about 15 to 20 minutes until thick enough to coat a spoon. Stir occasionally to prevent catching. Warm the drained chickpeas in the sauce or a separate saucepan until piping hot throughout.',
      'Divide the rice between two warm serving bowls, spoon over the cooked lentils and pasta, then add the tomato chilli sauce and chickpeas. Finish generously with the crispy fried onions, and serve the remaining sauce alongside.',
    ],
